class Solution {
    public int findMinStep(String board, String hand) {
        int[] handCount = new int[26];
        for (char c : hand.toCharArray()) handCount[c - 'A']++;
        java.util.Map<String, Integer> memo = new java.util.HashMap<>();
        int res = dfs(board, handCount, memo);
        return res == Integer.MAX_VALUE ? -1 : res;
    }
    private int dfs(String board, int[] hand, java.util.Map<String, Integer> memo) {
        if (board.isEmpty()) return 0;
        String key = board + java.util.Arrays.toString(hand);
        if (memo.containsKey(key)) return memo.get(key);
        int res = Integer.MAX_VALUE;
        int i = 0;
        while (i < board.length()) {
            int j = i;
            while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
            int need = 3 - (j - i);
            int ci = board.charAt(i) - 'A';
            if (hand[ci] >= need) {
                hand[ci] -= need;
                String newBoard = clean(board.substring(0, i) + board.substring(j));
                int sub = dfs(newBoard, hand, memo);
                if (sub != Integer.MAX_VALUE) res = Math.min(res, sub + need);
                hand[ci] += need;
            }
            i = j;
        }
        memo.put(key, res);
        return res;
    }
    private String clean(String s) {
        int i = 0;
        while (i < s.length()) {
            int j = i;
            while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
            if (j - i >= 3) { s = s.substring(0, i) + s.substring(j); i = 0; }
            else i = j;
        }
        return s;
    }
}

import java.util.*;

class Solution {
    public int findMinStep(String board, String hand) {
        char[] h = hand.toCharArray();
        Arrays.sort(h);
        String sortedHand = new String(h);
        Set<String> visited = new HashSet<>();
        Queue<String[]> queue = new LinkedList<>();
        queue.offer(new String[]{board, sortedHand});
        visited.add(board + "#" + sortedHand);
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int q = 0; q < size; q++) {
                String[] cur = queue.poll();
                String b = cur[0];
                String hd = cur[1];
                if (b.isEmpty()) return steps;
                for (int i = 0; i < hd.length(); i++) {
                    if (i > 0 && hd.charAt(i) == hd.charAt(i - 1)) continue;
                    char ball = hd.charAt(i);
                    String newHand = hd.substring(0, i) + hd.substring(i + 1);
                    for (int j = 0; j <= b.length(); j++) {
                        if (j < b.length() && b.charAt(j) != ball) continue;
                        if (j > 0 && b.charAt(j - 1) == ball) continue;
                        String newBoard = clean(b.substring(0, j) + ball + b.substring(j));
                        String key = newBoard + "#" + newHand;
                        if (!visited.contains(key)) {
                            visited.add(key);
                            queue.offer(new String[]{newBoard, newHand});
                        }
                    }
                }
            }
            steps++;
        }
        return -1;
    }
    private String clean(String s) {
        int i = 0;
        while (i < s.length()) {
            int j = i;
            while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
            if (j - i >= 3) { s = s.substring(0, i) + s.substring(j); i = 0; }
            else i = j;
        }
        return s;
    }
}
